import { createPayment } from '../../lib/payments'

export function CheckoutPage(amountCents = 1299): string {
  const payment = createPayment({ orderId: 'ord_1', amountCents })

  if (payment.state === 'failed') {
    return `Payment failed (${payment.id})`
  }

  const redirectUrl =
    'redirectUrl' in payment && typeof payment.redirectUrl === 'string'
      ? payment.redirectUrl
      : undefined

  return redirectUrl ?? 'Payment created'
}

